SELECT COUNT(*) FROM singer;
SELECT COUNT(*) AS total_number_of_musicians FROM singer;
SELECT Name, Country, Age FROM singer ORDER BY Age DESC LIMIT 100;
SELECT Name, Country, Age FROM singer ORDER BY Age DESC
SELECT AVG(Age), MIN(Age), MAX(Age) FROM singer;
SELECT AVG(Age), MIN(Age), MAX(Age) FROM singer;
SELECT singer.Name, singer.release_year FROM singer JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN stadium ON singer_in_concert.Concert_ID = concert.Concert_ID WHERE singer.Age < (SELECT AVG(Age) FROM singer) ORDER BY singer.Age ASC LIMIT 1;
SELECT singer.Name, concert.Year AS publish_year FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE singer.Age < (SELECT Age FROM singer ORDER BY Age ASC LIMIT 1);
SELECT DISTINCT Country FROM singer WHERE Age > 20;
SELECT DISTINCT s.Country, c.Year FROM singer s JOIN concert c ON s.Singer_ID = c.Singer_ID WHERE c.Year > 20;
SELECT State, COUNT(singer_in_concert.Singer_ID) AS number_of_vocalists FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY State
SELECT COUNT(DISTINCT singer.Singer_ID) AS total_musicians, singer.Country AS State FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Country
SELECT singer.Name, singer.Age FROM singer JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE singer.Age > (SELECT AVG(Age) FROM singer)
SELECT singer.Name, singer.Age FROM singer INNER JOIN stadium ON singer.Instrument = stadium.Stadium_ID INNER JOIN concert ON concert.Concert_ID = singer_in_concert.concert_ID WHERE singer.Age > (SELECT AVG(Age) FROM singer)
SELECT stadium.Name, concert.Stadium_ID FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Year BETWEEN 2020 AND 2025;
SELECT s.Name, c.Stadium_ID FROM singer s JOIN singer_in_concert c ON s.Singer_ID = c.Singer_ID JOIN concert c ON c.concert_ID = c.concert_ID WHERE c.Capacity BETWEEN 5000 AND 10000;
SELECT AVG(Capacity), MAX(Capacity) FROM stadium;
SELECT AVG(Capacity), MAX(Capacity) FROM stadium;
SELECT Name, AVG(Average) AS Average_Average FROM stadium INNER JOIN singer_in_concert ON stadium.Stadium_ID = singer_in_concert.Stadium_ID GROUP BY Name ORDER BY AVG(Average) DESC LIMIT 1
SELECT Name, AVG(Average) AS Average_Average FROM stadium JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID JOIN concert ON concert.concert_ID = singer_in_concert.concert_ID GROUP BY Name ORDER BY AVG(Average) DESC LIMIT 1
SELECT COUNT(*) FROM concert c JOIN singer_in_concert sc ON c.concert_ID = sc.concert_ID WHERE c.Year IN ('2014', '2015')
SELECT COUNT(*) FROM concert WHERE Year IN ('2014', '2015')
SELECT stadium.Name, COUNT(singer_in_concert.Singer_ID) AS total_shows FROM stadium JOIN singer_in_concert ON stadium.Stadium_ID = singer_in_concert.Stadium_ID GROUP BY stadium.Name
SELECT COUNT(*) AS total_shows_per_stadium FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID GROUP BY concert.Stadium_ID
SELECT concert.Name, COUNT(singer_in_concert.Singer_ID) AS show_count FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Year = 2014 OR concert.Year > 2014 GROUP BY concert.Name, concert.Stadium_ID ORDER BY show_count DESC;
SELECT s.Name, c.Year AS Year, c.Number_of_seats AS Number_of_seats FROM concert c JOIN singer_in_concert s ON c.concert_ID = singer_in_concert.concert_ID JOIN stadium s ON s.Stadium_ID = singer_in_concert.Singer_ID WHERE c.Year > 2013 AND c.Number_of_seats = (SELECT MAX(c.Number_of_seats) FROM concert c)
SELECT concert.Year, COUNT(singer_in_concert.Singer_ID) AS total_shows FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID GROUP BY concert.Year ORDER BY total_shows DESC LIMIT 1
SELECT concert.Year, COUNT(singer_in_concert.Singer_ID) AS total_shows FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID GROUP BY concert.Year ORDER BY total_shows DESC LIMIT 1;
