SELECT Name FROM stadium WHERE Capacity IS NULL OR Highest IS NULL OR Lowest IS NULL OR Average IS NULL;
SELECT DISTINCT Location FROM stadium WHERE Age > 40 OR Age < 30
SELECT Name FROM stadium WHERE Year != 2014
SELECT Name FROM stadium WHERE Year = 2014 AND Highest IS NULL OR Lowest IS NULL OR Average IS NULL;
SELECT singer.Name, singer.Instrumentation, singer_in_concert.Singer_ID FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Name, singer_in_concert.Singer_ID;
SELECT singer.Name, concert.Theme, singer_in_concert.Singer_ID AS Song_Singer_ID FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID;
SELECT singer.Name, COUNT(singer_in_concert.Singer_ID) AS total_shows FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID GROUP BY singer.Name
