SELECT singer.Name FROM singer JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Year = 2014;
SELECT DISTINCT singer.Name FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE concert.Year = '2014';
SELECT singer.Name, singer.Country FROM singer JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Theme LIKE '%Hey%'
SELECT singer.Name, singer.Country, singer_in_concert.Singer_ID FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID WHERE singer_in_concert.concert.Concert_Name LIKE '%Hey%'
SELECT s.Name, c.Year FROM stadium s JOIN concert c ON s.Stadium_ID = c.Stadium_ID WHERE c.Year IN (2014, 2015)
SELECT s.Name, c.Year FROM stadium s JOIN concert c ON s.Stadium_ID = c.Stadium_ID WHERE c.Year IN (2014, 2015)
SELECT COUNT(*) AS total_performances FROM concert JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Highest > concert.Lowest;
