SELECT COUNT(*) FROM continents;
SELECT COUNT(*) FROM continents;
SELECT continents.ContId, continents.Continent, COUNT(countries.CountryId) AS nations FROM continents JOIN countries ON countries.Continent = continents.ContId GROUP BY continents.Continent
SELECT continents.ContId, continents.Name, COUNT(countries.CountryId) AS total_states FROM continents JOIN countries ON countries.Continent = continents.ContId GROUP BY continents.ContId
SELECT COUNT(*) FROM countries;
SELECT COUNT(*) FROM countries;
SELECT DISTINCT c.Maker, c.Id, COUNT(c.Maker) AS num_models FROM car_makers c JOIN car_names ON c.Maker = c.Maker GROUP BY c.Maker;
SELECT car_makers.FullName, car_makers.Id, car_makers.Maker, model_list.Model, model_list.ModelCount FROM car_makers JOIN model_list ON car_makers.Id = model_list.Maker;
SELECT model_list.Model FROM model_list JOIN car_names ON car_names.MakeId = model_list.Maker JOIN car_makers ON car_makers.Id = car_names.MakeId GROUP BY model_list.Model ORDER BY model_list.MPGE DESC LIMIT 1;
SELECT model_list.ModelId FROM model_list JOIN car_names ON model_list.Model = car_names.Model JOIN car_makers ON car_makers.Id = car_names.MakeId JOIN countries ON countries.CountryId = car_makers.CountryId JOIN continents ON continents.ContId = countries.ContinentId WHERE car_makers.Maker = (SELECT Maker FROM car_makers WHERE Maker = (SELECT Maker FROM car_makers WHERE Maker IS NULL)) ORDER BY model_list.ModelId ASC LIMIT 1;
SELECT model_list.ModelId FROM model_list JOIN car_names ON model_list.Model = car_names.Model JOIN car_makers ON car_makers.Id = car_names.MakeId JOIN countries ON car_makers.CountryId = countries.CountryId JOIN continents ON countries.Continent = continents.ContId WHERE car_names.MPG < (SELECT AVG(MPG) FROM cars_data)
SELECT model_list.ModelId FROM model_list JOIN car_makers ON car_makers.Id = model_list.Maker JOIN countries ON countries.CountryId = car_makers.CountryId WHERE car_makers.CountryId = (SELECT CountryId FROM countries ORDER BY Weight ASC LIMIT 1) AND model_list.Maker = (SELECT Maker FROM car_makers ORDER BY Weight ASC LIMIT 1)
SELECT car_makers.FullName FROM car_makers JOIN countries ON car_makers.CountryId = countries.CountryId JOIN continents ON countries.Continent = continents.ContId WHERE countries.CountryName = 'USA' AND car_makers.Country = 'USA' AND cars_data.Year = 1970
SELECT MAKER, FULL_NAME FROM car_makers JOIN car_names ON car_makers.Id = car_names.MakeId JOIN model_list ON car_makers.Id = model_list.Maker JOIN countries ON model_list.Model = countries.CountryId JOIN continents ON countries.Continent = continents.ContId WHERE YEAR = 1970;
SELECT Make, Year FROM cars_data JOIN car_makers ON cars_data.Id = car_makers.Id JOIN model_list ON car_makers.Id = model_list.Maker JOIN car_names ON model_list.Model = car_names.Model ORDER BY Year ASC;
SELECT c.Maker, c.Year FROM car_makers c JOIN cars_data ON c.Id = cars_data.Id JOIN car_names ON c.MakeId = car_names.MakeId JOIN model_list ON c.MakeId = model_list.MakeId JOIN countries ON c.CountryId = countries.CountryId;
SELECT DISTINCT model_list.ModelId FROM model_list JOIN car_makers ON car_makers.Country = countries.CountryId JOIN car_names ON car_names.MakeId = car_makers.Id JOIN car_makers ON car_makers.Id = model_list.Maker JOIN cars_data ON car_names.Model = cars_data.Model WHERE cars_data.Year >= 1980;
SELECT DISTINCT ModelId FROM model_list JOIN car_names ON car_names.MakeId = model_list.Maker JOIN countries ON countries.CountryId = car_makers.CountryId WHERE Year > '1980'
SELECT c.Continent, COUNT(c.Continent) AS count FROM continents c JOIN countries ON c.Continent = countries.Continent JOIN car_makers ON countries.CountryId = car_makers.Country GROUP BY c.Continent
SELECT c.Continent, COUNT(c.Car_Maker) AS vehicle_manufacturers_per_continent FROM countries c JOIN continents on c.Continent = continents.ContId GROUP BY c.Continent;
SELECT CountryName FROM countries JOIN car_makers ON countries.CountryId = car_makers.CountryId GROUP BY CountryName ORDER BY COUNT(CountryName) DESC;
SELECT car_makers.FullName FROM car_makers WHERE car_makers.Country = (SELECT countries.CountryName FROM countries WHERE countries.CountryId = (SELECT countries.CountryId FROM countries WHERE countries.CountryId = (SELECT countries.CountryId FROM countries WHERE countries.CountryName = 'North America'))))
SELECT COUNT(*) AS count, manufacturers.FullName AS manufacturer_full_name FROM car_makers JOIN countries ON car_makers.Country = countries.CountryName JOIN car_names ON car_makers.MakeId = car_names.MakeId GROUP BY car_makers.Maker;
SELECT DISTINCT c.CountryName, m.Maker, m.Model, m.Id, m.FullName FROM countries c JOIN car_makers m ON c.CountryId = m.CountryId JOIN car_names ON m.MakeId = c.MakeId JOIN model_list ON m.ModelId = model_list.ModelId;
SELECT Accelerate FROM cars_data WHERE Year = '2023' AND CarNames.MakeId = 'AMC-HORSE' AND CarNames.Model = 'SPORTABOUT'
SELECT Accelerate, Year FROM cars_data WHERE Accelerate = (SELECT MAX(Accelerate) FROM model_list WHERE Model IN ('ACME', 'ACME') AND Maker IN ('ACME', 'ACME')
SELECT COUNT(DISTINCT Maker) FROM car_makers;
SELECT COUNT(*) FROM car_makers WHERE Country = 'France'
SELECT COUNT(DISTINCT model_list.Model) FROM model_list;
SELECT COUNT(*) FROM car_makers JOIN car_names ON car_makers.Id = car_names.MakeId JOIN countries ON car_makers.CountryId = countries.CountryId WHERE countries.Continent = 'United States'
SELECT AVG(MPG) FROM cars_data WHERE Cylinders = 4;
SELECT AVG(MPG) FROM cars_data WHERE Cylinders = 4;
SELECT MIN(Car_Makers.Weight) FROM car_makers JOIN model_list ON car_makers.Maker = model_list.Maker JOIN car_names ON model_list.Model = car_names.Model JOIN countries ON car_makers.Country = countries.CountryId WHERE car_makers.Year = 1974;
SELECT MIN(Weight) FROM cars_data WHERE Year = 1974 AND Cylinders = 8
SELECT car_makers.Maker, model_list.Model FROM car_makers JOIN model_list ON car_makers.Id = model_list.Maker;
SELECT car_makers.Maker, model_list.Model FROM car_makers JOIN model_list ON car_makers.Id = model_list.Maker;
SELECT countries.CountryName, countries.CountryId FROM countries JOIN car_makers ON countries.CountryId = car_makers.CountryId GROUP BY countries.CountryId;
SELECT DISTINCT countries.CountryName, car_makers.Maker, car_makers.FullName FROM countries JOIN car_makers ON countries.CountryId = car_makers.Country WHERE car_makers.Country IS NOT NULL AND car_makers.Maker IS NOT NULL AND car_makers.Country IN (SELECT countries.Continent FROM continents) ORDER BY countries.CountryName;
SELECT COUNT(*) FROM cars_data WHERE Horsepower > 150
SELECT COUNT(*) FROM cars_data WHERE Horsepower > 150;
SELECT AVG(Cars_Data.Weight) AS average_weight FROM cars_data;
SELECT AVG(Car_Makers.Weight), Year FROM cars_data JOIN car_makers ON cars_data.Id = car_makers.Id;
SELECT DISTINCT countries.CountryName, car_makers.Maker FROM countries JOIN car_makers ON countries.CountryId = car_makers.CountryId WHERE car_makers.Maker IS NOT NULL AND car_makers.Maker IN (SELECT MAKER FROM car_makers WHERE Cylinders IS NOT NULL AND Horsepower IS NOT NULL AND Weight IS NOT NULL AND Accelerate IS NOT NULL AND Year IS NOT NULL)
