SELECT s.first_name, s.student_id FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON s.section_id = ssec.section_id JOIN Semesters ssem ON ssec.semester_id = ssem.semester_id JOIN Departments d ON ssec.degree_program_id = d.department_id JOIN Degree_Programs dp ON d.department_id = dp.department_id;
SELECT s.semester_name, s.student_id, s.first_name, s.last_name FROM Semesters s JOIN Students student ON s.semester_id = student.semester_id JOIN Student_Enrolment_Courses course_enrolment ON student.student_id = course_enrolment.student_course_id JOIN Courses course ON course_enrolment.course_id = course.course_id JOIN Sections section ON section.section_id = course_enrolment.course_id JOIN Departments department ON section.department_id = department.department_id JOIN Degree_Programs degree_program ON section.section_id = degree_program.department_id WHERE s.semester_description = (SELECT semester_description FROM Semesters WHERE semester_id = s.semester_id)
