SELECT DISTINCT d.department_name, d.department_description FROM Departments d JOIN Degree_Programs dp ON d.department_id = dp.department_id WHERE d.department_name LIKE '%computer%' OR d.department_description LIKE '%computer%' OR d.department_name LIKE '%computer%' OR d.department_description LIKE '%computer%'
SELECT s.first_name, s.middle_name, s.last_name, s.id FROM Students s JOIN Student_Enrolment_Courses sc ON s.id = sc.student_enrolment_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections s2 ON s2.section_id = sc.section_id JOIN Semester s3 ON s2.semester_id = s3.semester_id JOIN Degree_Programs d ON s2.degree_program_id = d.degree_program_id JOIN Departments d2 ON d.department_id = d2.department_id;
SELECT s.middle_name, s.family_name, s.student_id, d.degree_program_id, d.department_id FROM Students s JOIN Degree_Programs d ON s.student_id = d.degree_program_id JOIN Departments ON d.department_id = Departments.department_id WHERE d.degree_summary_name = '2 degree programs' AND d.degree_summary_description = 'one term'
SELECT s.first_name, s.middle_name, s.last_name, s.other_student_details FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections s2 ON sc.course_id = s2.course_id JOIN Departments d ON s2.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Transcripts t ON dp.degree_program_id = t.transcript_id JOIN Transcript_Contents tc ON tc.student_course_id = sc.student_course_id WHERE dp.degree_summary_name = 'Bachelor Degree Program'
SELECT middle_name, family_name, first_name FROM Students INNER JOIN Addresses ON Students.current_address_id = Addresses.address_id INNER JOIN Departments ON Students.student_id = Departments.department_id INNER JOIN Degree_Programs ON Students.student_id = Degree_Programs.degree_program_id INNER JOIN Sections ON Degree_Programs.department_id = Sections.department_id INNER JOIN Courses ON Sections.course_id = Courses.course_id INNER JOIN Student_Enrolment_Courses ON Student_Enrolment_Courses.course_id = Courses.course_id INNER JOIN Student_Enrolment ON Student_Enrolment_Courses.student_enrolment_id = Student_Enrolment.student_id;
SELECT D.degree_summary_name, COUNT(D.degree_program_id) AS total_students_enrolled FROM Degree_Programs D JOIN Departments ON D.department_id = Departments.department_id GROUP BY D.degree_summary_name ORDER BY total_students_enrolled DESC;
SELECT DISTINCT Degree_Programs.degree_summary_name, COUNT(DISTINCT Students.student_id) AS student_count FROM Degree_Programs JOIN Students ON Degree_Programs.department_id = Students.department_id GROUP BY Degree_Programs.degree_summary_name ORDER BY student_count DESC;
SELECT D.degree_program_id, S.first_name, D.degree_summary_name FROM Degree_Programs D JOIN Students S ON D.department_id = S.department_id JOIN Sections S2 ON S2.section_id = S.student_id JOIN Courses C ON S2.course_id = C.course_id JOIN Transcripts T ON S2.transcript_id = T.transcript_id JOIN Transcript_Contents TC ON T.transcript_id = TC.transcript_id JOIN Student_Enrolment_Courses SC ON TC.student_course_id = SC.student_course_id JOIN Student_Enrolment SE ON SC.student_enrolment_id = SE.student_enrolment_id JOIN Degree_Programs DE ON SE.degree_program_id = DE.degree_program_id GROUP BY D.degree_program_id, S.first_name, D.degree_summary_name ORDER BY D.degree_summary_name ASC;
SELECT D.degree_program_id, D.degree_summary_name, D.degree_summary_description, D.degree_program_id FROM Degree_Programs D JOIN Students S ON D.department_id = S.department_id JOIN Students S2 ON D.department_id = S2.department_id WHERE D.degree_summary_name IS NOT NULL AND D.degree_summary_description IS NOT NULL ORDER BY D.degree_program_id DESC
SELECT s.id, s.first_name, s.middle_name, s.last_name, s.date_first_registered, s.date_left, s.student_enrolment_count, s.student_enrolment_id FROM Students s JOIN Student_Enrolment_Courses c ON s.student_id = c.student_course_id JOIN Courses ON c.course_id = Courses.course_id JOIN Sections ON c.course_id = Sections.course_id JOIN Semester ON c.semester_id = Semesters.semester_id JOIN Degree_Programs ON c.degree_program_id = Degree_Programs.degree_program_id GROUP BY s.id, s.first_name, s.middle_name, s.last_name, s.date_first_registered, s.date_left, s.student_enrolment_count ORDER BY s.student_enrolment_count DESC;
SELECT s.middle_name, s.id, COUNT(se.student_id) AS enrollments FROM Students s JOIN Student_Enrolment_Courses sc ON s.id = sc.student_course_id JOIN Student_Enrolment se ON se.student_id = s.id GROUP BY s.id ORDER BY enrollments DESC LIMIT 1;
SELECT section_name FROM Sections WHERE section_description IS NULL;
SELECT DISTINCT student.first_name FROM Students INNER JOIN Addresses ON Students.current_address_id = Addresses.address_id WHERE Addresses.state_province_county IS NULL;
SELECT course_name FROM Courses WHERE course_id IN (SELECT course_id FROM Student_Enrolment_Courses WHERE student_course_id IN (SELECT course_id FROM Student_Enrolment_Courses WHERE student_enrolment_id IN (SELECT student_enrolment_id FROM Student_Enrolment_Courses WHERE course_id IN (SELECT course_id FROM Students WHERE student_id IN (SELECT student_id FROM Students WHERE current_address_id = (SELECT address_id FROM Addresses WHERE address_id IN (SELECT address_id FROM Addresses WHERE state_province_county = 'California' AND country = 'US')))) AND date_first_registered IS NOT NULL)) AND date_left IS NULL)
SELECT course_name, course_description, other_details FROM Courses INNER JOIN Sections ON Courses.course_id = Sections.course_id;
SELECT course_name, COUNT(*) AS enrollment_count FROM Courses JOIN Student_Enrolment_Courses ON Courses.course_id = Student_Enrolment_Courses.course_id GROUP BY course_name ORDER BY enrollment_count DESC LIMIT 1;
SELECT course_name FROM Courses JOIN Degree_Programs ON Courses.course_id = Degree_Programs.degree_program_id GROUP BY course_name ORDER BY COUNT(*) DESC LIMIT 1
SELECT DISTINCT Students.last_name FROM Students JOIN Addresses ON Addresses.address_id = Students.current_address_id JOIN Addresses ON Addresses.address_id = Students.permanent_address_id WHERE Addresses.state_province_county = 'North Carolina' AND Addresses.state_province_county IS NULL;
SELECT s.last_name, s.permanent_address_id, s.first_name, s.middle_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Addresses s JOIN Students t ON s.address_id = t.current_address_id WHERE s.state_province_county = 'North Carolina' AND t.date_left IS NULL
SELECT S.student_id, S.date_first_registered, S.date_left, S.date_first_registered, S.date_left, S.date_first_registered, S.date_left FROM Students S WHERE S.date_first_registered IS NOT NULL AND S.date_left IS NOT NULL AND S.date_first_registered >= (SELECT date_left FROM Students) ORDER BY S.date_first_registered DESC;
SELECT s.student_id, s.date_first_registered, s.date_left, s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections s2 ON s2.course_id = c.course_id JOIN Departments d ON s2.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = s2.department_id WHERE c.course_description = 'curriculums' AND c.course_description IS NOT NULL GROUP BY s.student_id, s.date_first_registered, s.date_left, s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details
