SELECT student_id, last_name, cell_mobile_number FROM Students WHERE first_name = 'Timothy' AND last_name = 'Ward';
SELECT s.first_name, s.middle_name, s.last_name, s.date_first_registered FROM Students s WHERE s.date_first_registered IS NOT NULL ORDER BY s.date_first_registered ASC;
SELECT s.middle_name, s.first_name, s.last_name FROM Students s WHERE s.date_first_registered = (SELECT MAX(date_first_registered) FROM Students)
SELECT s.first_name, s.middle_name, s.last_name, s.date_first_registered, s.date_left, s.other_student_details FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssc ON sc.course_id = ssc.course_id JOIN Semesters sse ON ssc.semester_id = sse.semester_id JOIN Degree_Programs dp ON ssc.degree_program_id = dp.degree_program_id JOIN Departments d ON dp.department_id = d.department_id WHERE s.date_first_registered IS NULL OR s.date_left IS NULL ORDER BY s.date_first_registered ASC;
SELECT s.middle_name, s.last_name, s.middle_name AS middle_name, s.last_name AS family_name FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id JOIN Courses c ON s.current_address_id = a.address_id JOIN Transcripts t ON s.current_address_id = t.transcript_date JOIN Student_Enrolment_Courses sc ON s.current_address_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON sc.section_id = ssec.section_id JOIN Semesters ssem ON ssec.semester_id = ssem.semester_id;
SELECT s.first_name, s.permanent_address_id, s.permanent_address_line_1, s.permanent_address_line_2, s.permanent_address_line_3, s.permanent_address_city, s.permanent_address_state_province_county, s.permanent_address_zip_postcode, s.permanent_address_other_details FROM Students s JOIN Addresses ON s.permanent_address_id = Addresses.address_id WHERE s.permanent_address_id != s.current_address_id;
SELECT s.first_name, s.middle_name, s.last_name FROM Students s WHERE s.permanent_address_id = s.permanent_address_id AND s.permanent_address_id != s.current_address_id;
SELECT s.place_id, s.lines FROM Addresses s JOIN Student_Enrolment_Courses sc ON s.address_id = sc.student_enrolment_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections s2 ON sc.section_id = s2.section_id JOIN Semesters s3 ON s2.semester_id = s3.semester_id JOIN Departments d ON s2.department_id = d.department_id JOIN Degree_Programs dp ON d.department_id = dp.department_id JOIN Courses c2 ON dp.degree_program_id = c2.course_id JOIN Students s2 ON s2.student_id = dp.student_id JOIN Transcripts t ON dp.degree_program_id = t.degree_program_id JOIN Transcript_Contents tc ON t.transcript_id = tc.transcript_id GROUP BY s.place_id, s.lines ORDER BY s.place_id ASC;
SELECT S.id, S.line_1, S.line_2 FROM Addresses S JOIN Students S ON S.address_id = S.current_address_id JOIN Student_Enrolment_Courses SC ON S.student_id = SC.student_course_id JOIN Courses C ON SC.course_id = C.course_id JOIN Sections S1 ON S.section_id = S1.section_id JOIN Semesters S2 ON S1.semester_id = S2.semester_id JOIN Departments D ON D.department_id = S1.department_id JOIN Degree_Programs DP ON D.department_id = DP.department_id JOIN Student_Enrolment SE ON DP.degree_program_id = SE.degree_program_id JOIN Transcript_Contents TC ON SE.student_id = TC.student_course_id JOIN Transcripts T ON TC.transcript_id = T.transcript_id;
SELECT AVG(transcript_date) FROM Transcripts;
SELECT AVG(date_left) AS average_student_record_date FROM Students;
SELECT t.transcript_date, s.first_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_left FROM Addresses s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_enrolment_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON sc.course_id = ssec.course_id JOIN Departments d ON ssec.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Transcripts t ON dp.degree_program_id = t.transcript_id JOIN Student_Enrolment st ON st.student_id = s.student_id JOIN Semesters ssem ON st.semester_id = ssem.semester_id WHERE st.date_left IS NULL;
