SELECT MAX(course_id), MAX(semester_description) FROM Semesters INNER JOIN Sections ON Semesters.semester_id = Sections.semester_id INNER JOIN Courses ON Sections.course_id = Courses.course_id INNER JOIN Student_Enrolment_Courses ON Sections.section_id = Student_Enrolment_Courses.course_id INNER JOIN Courses ON Student_Enrolment_Courses.course_id = Courses.course_id;
SELECT s.student_id, s.date_first_registered, s.date_left, s.date_left AS date_left FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_enrolment_id JOIN Student_Enrolment se ON sc.course_id = se.course_id JOIN Courses c ON se.course_id = c.course_id JOIN Departments d ON se.department_id = d.department_id JOIN Degree_Programs dp ON se.degree_program_id = dp.degree_program_id JOIN Transcripts t ON se.semester_id = t.semester_id JOIN Transcript_Contents tc ON se.student_id = tc.student_course_id ORDER BY s.date_first_registered ASC LIMIT 1;
