SELECT DISTINCT s.student_id, s.first_name, s.last_name, s.cell_mobile_number, s.email_address, s.date_first_registered, s.date_left FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON s.section_id = ssec.section_id JOIN Semesters ssem ON ssec.semester_id = ssem.semester_id JOIN Departments d ON ssec.degree_program_id = d.department_id JOIN Degree_Programs dp ON d.department_id = dp.department_id;
SELECT S.student_id, D.department_id, D.department_name, D.department_description FROM Students S JOIN Departments D ON S.current_address_id = D.department_id WHERE D.department_id IN (SELECT department_id FROM Degree_Programs WHERE degree_program_id IN (SELECT degree_program_id FROM Degree_Programs WHERE degree_summary_name = 'Masters')) AND D.department_id IN (SELECT department_id FROM Degree_Programs WHERE degree_program_id IN (SELECT degree_program_id FROM Degree_Programs WHERE degree_summary_name = 'Bachelors'))
