SELECT owners.state, dogs.dog_id, dogs.name, dogs.age, dogs.date_of_birth, dogs.gender, dogs.date_departed, treatments.date_of_treatment, treatments.cost_of_treatment FROM Owners JOIN Dogs ON Owners.owner_id = Dogs.owner_id JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id JOIN Breeds ON Dogs.breed_code = Breeds.breed_code WHERE dogs.state IS NOT NULL AND dogs.gender = 'Male' AND dogs.date_of_birth IS NOT NULL AND dogs.date_departed IS NOT NULL AND treatments.date_of_treatment IS NOT NULL AND treatments.cost_of_treatment IS NOT NULL;
SELECT Owners.state FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id INNER JOIN Professionals ON Dogs.owner_id = Professionals.professional_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code INNER JOIN Breeds ON Dogs.breed_code = Breeds.breed_code;
SELECT AVG(Dogs.age) AS average_age FROM Dogs;
SELECT AVG(Dogs.age) FROM Dogs;
SELECT Dogs.owner_id, Owners.first_name, Owners.last_name, Owners.cell_number FROM Owners JOIN Dogs ON Owners.owner_id = Dogs.owner_id WHERE Owners.state = 'Indiana' OR Dogs.dog_id IN (SELECT dog_id FROM Charges WHERE charge_amount > 2)
SELECT Dogs.id, Dogs.last_name, Professionals.last_name FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.state = 'Indiana' OR Professionals.cell_number IS NOT NULL AND Professionals.cell_number IS NOT NULL AND Professionals.cell_number IS NOT NULL;
SELECT Dogs.name FROM Dogs WHERE Dogs.date_of_birth IS NULL OR Dogs.date_of_birth IS NOT NULL AND (SELECT Charges.charge_amount FROM Charges WHERE Charges.charge_type = 'health-care' AND Charges.charge_amount <= 1000)
SELECT Dogs.name FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Treatments.cost_of_treatment > 1000;
SELECT o.first_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatment_Types t ON d.dog_id = t.dog_id JOIN Professionals p ON d.professional_id = p.professional_id WHERE o.first_name NOT IN (SELECT o.first_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatment_Types t ON d.dog_id = t.dog_id JOIN Professionals p ON d.professional_id = p.professional_id) AND o.first_name IS NOT NULL;
SELECT Dogs.first_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.breed_code IS NULL OR Dogs.size_code IS NULL OR Dogs.name IS NULL AND Dogs.owner_id IS NOT NULL AND Dogs.owner_id IN (SELECT Owners.owner_id FROM Owners WHERE Owners.first_name IS NULL OR Owners.first_name IS NOT NULL AND Owners.last_name IS NULL OR Owners.last_name IS NOT NULL) AND Dogs.owner_id IN (SELECT Professionals.professional_id FROM Professionals WHERE Professionals.first_name IS NULL OR Professionals.first_name IS NOT NULL AND Professionals.last_name IS NULL OR Professionals.last_name IS NOT NULL)
SELECT o.owner_id, p.role_code, p.email_address FROM Owners o INNER JOIN Professionals p ON o.owner_id = p.professional_id WHERE p.role_code = 'Veterinarian' AND p.email_address IS NULL;
SELECT Dogs.id, Dogs.role, Dogs.email_address FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Professionals.role_code = 'Veterinarian' AND Dogs.dog_id NOT IN (SELECT dog_id FROM Treatments WHERE treatment_type_code = 'Health Care' OR treatment_type_code = 'Other')
SELECT o.owner_id, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number, d.name, d.age, d.date_of_birth, d.gender, d.date_departed FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id ORDER BY d.age DESC LIMIT 1;
SELECT Dogs.owner_id, Dogs.name, Dogs.family_name FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id GROUP BY Dogs.owner_id ORDER BY Dogs.name, Dogs.family_name DESC LIMIT 1;
SELECT Dogs.owner_id, Dogs.role, Dogs.first_name, Dogs.breed_code, Dogs.size_code, Dogs.name, Dogs.age, Dogs.date_of_birth, Dogs.gender, Dogs.date_departed FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.breed_code IS NOT NULL AND Dogs.size_code IS NOT NULL AND Dogs.name IS NOT NULL AND Dogs.age IS NOT NULL AND Dogs.date_of_birth IS NOT NULL AND Dogs.gender IS NOT NULL AND Dogs.date_departed IS NOT NULL
SELECT Dogs.id, Dogs.first_name, Dogs.last_name, Professionals.role_code, Professionals.first_name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Professionals.role_code = 'Veterinarian' AND Dogs.dog_id IN (SELECT Dogs.dog_id FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id WHERE Treatments.treatment_type_code = 'Health Care' GROUP BY Dogs.dog_id HAVING COUNT(Treatments.treatment_type_code) > 1)
SELECT breed_name FROM Breeds ORDER BY age DESC LIMIT 1;
SELECT breed_name FROM Breeds ORDER BY breed_code ASC LIMIT 1;
SELECT o.owner_id, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number, d.dog_id, d.name, d.age, d.date_of_birth, d.gender, d.weight, d.date_arrived, d.date_departed, t.cost_of_treatment, t.treatment_type_description, t.date_of_treatment FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Treatment_Types t1 ON t.treatment_type_code = t1.treatment_type_code JOIN Professionals p ON t.professional_id = p.professional_id GROUP BY o.owner_id, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number, d.dog_id, d.name, d.age, d.date_of_birth, d.gender, d.weight, d.date_arrived, d.date_departed, t.cost_of_treatment, t.treatment_type_description, t.date_of_treatment ORDER BY t.cost_of_treatment DESC;
SELECT Dogs.guardian_id, Dogs.family_name, MAX(Treatments.cost_of_treatment) AS max_cost FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id GROUP BY Dogs.dog_id ORDER BY max_cost DESC LIMIT 1;
SELECT MIN(cost_of_treatment) AS cost_of_treatment, treatment_type_description FROM Treatments INNER JOIN Dogs ON Treatments.dog_id = Dogs.dog_id GROUP BY treatment_type_code;
